      "7-1": {
        "refs": "M19:10,11,13,15,26",
        "text": "Danh sách gồm Talent và office; lọc tên/trạng thái/ngày không đăng/category/người phụ trách. M-07 có nút sang M-21 để sửa hồ sơ; không còn mô tả hồ sơ chỉ nhập qua ChatGPT.",
        "open": "Loại phân công theo category hay cá nhân vẫn KS 20261120 No.10/QA No.6."
      },
      "3-1": {
        "refs": "M19:19,20,27;BF19:18",
        "text": "Chỉ thị toàn bộ/category/Talent, ưu tiên Talent > category > toàn bộ; mọi trường hợp vẫn kiểm từ cấm. Có thử trên Talent, lưu, lịch sử và quay một phiên bản; sửa qua quản trị hoặc ChatGPT.",
        "open": "Nhiều category xung đột và hiệu lực thay chỉ thị với bài đã tạo vẫn cần phương án đội."
      },
      "EXT-INSTRUCTION": {
        "refs": "M19:19,20,27;BF19:18",
        "text": "Chỉ thị toàn bộ/category/Talent, ưu tiên Talent > category > toàn bộ; mọi trường hợp vẫn kiểm từ cấm. Có thử trên Talent, lưu, lịch sử và quay một phiên bản; sửa qua quản trị hoặc ChatGPT.",
        "open": "Nhiều category xung đột và hiệu lực thay chỉ thị với bài đã tạo vẫn cần phương án đội."
