      "3-7": {
        "refs": "T19:16,24;M19:6;BF19:13",
        "text": "Đạt mục tiêu có thông báo; follower tăng được truyền qua lời nhắn AI theo chỉ thị.",
        "open": "Mốc 25/50/75% ở QA No.14 và cách mới nêu trong màn 19/11 cần đối chiếu, không tự bỏ hay thêm thông báo mốc."
      },
      "3-8": {
        "refs": "T19:16,27;M19:22",
        "text": "Tổng kết hằng tuần; ngày gửi chọn được trên M-17. Ngày thứ Hai là đề xuất trước, không phải lịch bất biến.",
        "open": "Không phát sinh quyết định nghiệp vụ mới từ phần nguồn này; các đề xuất kỹ thuật cũ vẫn là đề xuất."
      },
      "3-9": {
        "refs": "M19:22;BF19:11;KS:20261120:20",
        "text": "3 ngày nhắc Talent/7 ngày báo Manager là giá trị ban đầu chỉnh tại M-17; không phải con số cố định cho mọi đợt.",
        "open": "Áp dụng đếm ngày không đăng cho Talent ở chế độ tự động vẫn KS 20261120 No.20; cách đếm office chưa tự suy từ Talent."
      },
      "4-1": {
        "refs": "T19:12,13,17,18,27,30;BF19:6,7",
        "text": "AI tạo chữ/hashtag, dùng ảnh/video Talent gửi; không tự biến ảnh thành slideshow trong luồng bài thường. Bài ảnh không đăng YouTube.",
        "open": "Thứ tự ảnh→chữ hay chữ→ảnh còn KS 20261120 No.7; hiển thị kịch bản/video-idea còn No.35,36, không coi giá hiển thị là đã tạo video."
      },
      "4-2": {
        "refs": "T19:18,27,29;USER:DEC-0001",
        "text": "Không giới hạn số lần AI viết lại theo DEC-0001; quyền sửa tay giữ nguyên. Các mô tả hai lượt trong PDF19/11 là lịch sử bị thay đúng chủ đề.",
        "open": "Xử lý lỗi/kết quả không rõ/gửi lặp còn do đội thiết kế."
